cat > internal/store/customers.go <<'EOF'
package store

import (
	"sort"
	"strings"
	"time"
)

// deletedKeep is how long a deleted customer can be restored, and so how long it is kept before PurgeDeletedCustomers
// removes it.
const deletedKeep = 30 * 24 * time.Hour

// emailKey is the index key of a customer's email address: unique within one organization, ignoring case.
func emailKey(orgID, email string) string { return orgID + "\x00" + normEmail(email) }

// CreateCustomer adds a customer to an organization. A customer's email address is unique within the organization,
// ignoring case.
func (s *Store) CreateCustomer(orgID, name, email string, now time.Time) (Customer, error) {
	name, email = strings.TrimSpace(name), strings.TrimSpace(email)
	if name == "" || !validEmail(email) {
		return Customer{}, invalid("a customer needs a name and a valid email address")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[orgID]; !ok {
		return Customer{}, ErrNotFound
	}
	key := emailKey(orgID, email)
	if _, ok := s.customersByEmail[key]; ok {
		return Customer{}, ErrEmailTaken
	}
	c := Customer{ID: s.newID("cus"), OrgID: orgID, Name: name, Email: email, CreatedAt: now.UTC()}
	s.customers[c.ID] = c
	s.customersByEmail[key] = c.ID
	return c, nil
}

// Customer returns one of an organization's customers that is not deleted.
func (s *Store) Customer(orgID, id string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt != nil {
		return Customer{}, false
	}
	return copyCustomer(c), true
}

// CustomerIncludingDeleted returns one of an organization's customers, deleted or not (for invoices, which keep their
// customer's name and email after it is deleted).
func (s *Store) CustomerIncludingDeleted(orgID, id string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID {
		return Customer{}, false
	}
	return copyCustomer(c), true
}

// CustomerByID returns a customer of any organization, deleted or not (background jobs and the admin tool).
func (s *Store) CustomerByID(id string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	return copyCustomer(c), ok
}

// Customers returns an organization's customers that are not deleted, oldest first.
func (s *Store) Customers(orgID string) []Customer { return s.customersOf(orgID, false) }

// CustomersIncludingDeleted returns an organization's customers, deleted ones too, oldest first.
func (s *Store) CustomersIncludingDeleted(orgID string) []Customer { return s.customersOf(orgID, true) }

func (s *Store) customersOf(orgID string, deleted bool) []Customer {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Customer{}
	for _, c := range s.customers {
		if c.OrgID == orgID && (deleted || c.DeletedAt == nil) {
			out = append(out, copyCustomer(c))
		}
	}
	sortCustomers(out)
	return out
}

// SearchCustomers returns an organization's customers that are not deleted and whose name or email contains q, ignoring
// case, oldest first.
func (s *Store) SearchCustomers(orgID, q string) []Customer {
	q = strings.ToLower(strings.TrimSpace(q))
	out := []Customer{}
	for _, c := range s.Customers(orgID) {
		if strings.Contains(strings.ToLower(c.Name), q) || strings.Contains(strings.ToLower(c.Email), q) {
			out = append(out, c)
		}
	}
	return out
}

// FindCustomerByEmail returns the organization's customer that is not deleted and has this email address, ignoring case.
func (s *Store) FindCustomerByEmail(orgID, email string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	id, ok := s.customersByEmail[emailKey(orgID, email)]
	if !ok {
		return Customer{}, false
	}
	return copyCustomer(s.customers[id]), true
}

// UpdateCustomer changes a customer that is not deleted with f, which may refuse with an error. The ID, organization and
// deletion time cannot change.
func (s *Store) UpdateCustomer(orgID, id string, f func(*Customer) error) (Customer, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.customers[id]
	if !ok || old.OrgID != orgID || old.DeletedAt != nil {
		return Customer{}, ErrNotFound
	}
	c := copyCustomer(old)
	if err := f(&c); err != nil {
		return Customer{}, err
	}
	c.ID, c.OrgID, c.CreatedAt, c.DeletedAt = old.ID, old.OrgID, old.CreatedAt, nil
	c.Name, c.Email = strings.TrimSpace(c.Name), strings.TrimSpace(c.Email)
	if c.Name == "" || !validEmail(c.Email) {
		return Customer{}, invalid("a customer needs a name and a valid email address")
	}
	if c.DefaultPaymentMethod != "" && !strings.HasPrefix(c.DefaultPaymentMethod, "pm_") {
		return Customer{}, invalid("a payment method looks like pm_...")
	}
	if newKey := emailKey(orgID, c.Email); newKey != emailKey(orgID, old.Email) {
		if _, ok := s.customersByEmail[newKey]; ok {
			return Customer{}, ErrEmailTaken
		}
		delete(s.customersByEmail, emailKey(orgID, old.Email))
		s.customersByEmail[newKey] = c.ID
	}
	s.customers[id] = c
	return copyCustomer(c), nil
}

// DeleteCustomer erases a customer at once, keeping nothing: its invoices lose their customer. The API deletes customers
// with SoftDeleteCustomer; this is for undoing the creation of a customer.
func (s *Store) DeleteCustomer(orgID, id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID {
		return ErrNotFound
	}
	s.unindexCustomer(c)
	delete(s.customers, id)
	return nil
}

// SoftDeleteCustomer deletes a customer at now. It is hidden from the API and its email address is free again, but it is
// kept with its invoices and payments: RestoreCustomer undoes the deletion until PurgeDeletedCustomers removes it. A
// customer with a subscription that is not canceled cannot be deleted (ErrHasActiveSubscriptions).
func (s *Store) SoftDeleteCustomer(orgID, id string, now time.Time) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt != nil {
		return ErrNotFound
	}
	for _, sub := range s.subs {
		if sub.OrgID == orgID && sub.CustomerID == id && sub.Status != Canceled {
			return ErrHasActiveSubscriptions
		}
	}
	s.unindexCustomer(c)
	t := now.UTC()
	c.DeletedAt = &t
	s.customers[id] = c
	return nil
}

// RestoreCustomer undoes SoftDeleteCustomer, if the customer was deleted no more than 30 days before now. Its email address
// must not be in use by another customer of the organization (ErrEmailTaken).
func (s *Store) RestoreCustomer(orgID, id string, now time.Time) (Customer, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt == nil || c.DeletedAt.Before(now.Add(-deletedKeep)) {
		return Customer{}, ErrNotFound
	}
	key := emailKey(orgID, c.Email)
	if _, ok := s.customersByEmail[key]; ok {
		return Customer{}, ErrEmailTaken
	}
	c.DeletedAt = nil
	s.customers[id] = c
	s.customersByEmail[key] = id
	return copyCustomer(c), nil
}

// PurgeDeletedCustomers removes the customers deleted more than 30 days before now, for good, and returns how many it
// removed. Their invoices and payments stay, without their customer.
func (s *Store) PurgeDeletedCustomers(now time.Time) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	cutoff := now.Add(-deletedKeep)
	n := 0
	for id, c := range s.customers {
		if c.DeletedAt != nil && c.DeletedAt.Before(cutoff) {
			s.unindexCustomer(c)
			delete(s.customers, id)
			n++
		}
	}
	return n
}

// unindexCustomer forgets a customer's email address, if it is the one indexed for it. The caller holds the lock.
func (s *Store) unindexCustomer(c Customer) {
	if k := emailKey(c.OrgID, c.Email); s.customersByEmail[k] == c.ID {
		delete(s.customersByEmail, k)
	}
}

func copyCustomer(c Customer) Customer {
	if c.Metadata != nil {
		m := make(map[string]string, len(c.Metadata))
		for k, v := range c.Metadata {
			m[k] = v
		}
		c.Metadata = m
	}
	if c.DeletedAt != nil {
		t := *c.DeletedAt
		c.DeletedAt = &t
	}
	return c
}

func sortCustomers(cs []Customer) {
	sort.Slice(cs, func(i, j int) bool {
		if !cs[i].CreatedAt.Equal(cs[j].CreatedAt) {
			return cs[i].CreatedAt.Before(cs[j].CreatedAt)
		}
		return cs[i].ID < cs[j].ID
	})
}
EOF
