func TestSoftDeleteCustomer(t *testing.T) {
	s := New()
	a, b := newOrg(t, s, "A"), newOrg(t, s, "B")
	jane, _ := s.CreateCustomer(a.ID, "Jane Doe", "jane@example.com", t0)
	john, _ := s.CreateCustomer(a.ID, "John Roe", "john@example.com", t0)
	if err := s.SoftDeleteCustomer(b.ID, jane.ID, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("deleted through another org: %v", err)
	}
	at := t0.Add(time.Hour)
	if err := s.SoftDeleteCustomer(a.ID, jane.ID, at); err != nil {
		t.Fatal(err)
	}
	if err := s.SoftDeleteCustomer(a.ID, jane.ID, at); !errors.Is(err, ErrNotFound) {
		t.Fatalf("deleted twice: %v", err)
	}
	if _, ok := s.Customer(a.ID, jane.ID); ok {
		t.Fatal("deleted customer is still found")
	}
	if _, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); ok {
		t.Fatal("deleted customer is still found by email")
	}
	if got := s.Customers(a.ID); len(got) != 1 || got[0].ID != john.ID {
		t.Fatalf("Customers = %+v", got)
	}
	if got := s.SearchCustomers(a.ID, "jane"); len(got) != 0 {
		t.Fatalf("SearchCustomers = %+v", got)
	}
	if got := s.CustomersIncludingDeleted(a.ID); len(got) != 2 {
		t.Fatalf("CustomersIncludingDeleted = %+v", got)
	}
	got, ok := s.CustomerIncludingDeleted(a.ID, jane.ID)
	if !ok || got.DeletedAt == nil || !got.DeletedAt.Equal(at) {
		t.Fatalf("CustomerIncludingDeleted = %+v, %v", got, ok)
	}
	if _, err := s.UpdateCustomer(a.ID, jane.ID, func(c *Customer) error { c.Name = "Changed"; return nil }); !errors.Is(err, ErrNotFound) {
		t.Fatalf("updated a deleted customer: %v", err)
	}
	if _, err := s.CreateCustomer(a.ID, "Jane Again", "JANE@example.com", t0); err != nil {
		t.Fatalf("the email of a deleted customer is not free: %v", err)
	}
	if _, err := s.CreateCustomer(b.ID, "Jane", "jane@example.com", t0); err != nil {
		t.Fatalf("another org's email: %v", err)
	}
}

func TestDeleteWithActiveSubscription(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	c, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	p, _ := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: "USD", UnitAmount: 100, Interval: Monthly}, t0)
	sub, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: c.ID, PlanID: p.ID, Quantity: 1, Status: PastDue}, t0)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.SoftDeleteCustomer(a.ID, c.ID, t0); !errors.Is(err, ErrHasActiveSubscriptions) || !errors.Is(err, ErrConflict) {
		t.Fatalf("delete with a past due subscription: %v", err)
	}
	canceled := sub
	canceled.Status = Canceled
	if _, err := s.UpdateSubscription(a.ID, sub.ID, func(x *Subscription) error { x.Status = Canceled; return nil }); err != nil {
		t.Fatal(err)
	}
	_ = canceled
	if err := s.SoftDeleteCustomer(a.ID, c.ID, t0); err != nil {
		t.Fatalf("delete with only canceled subscriptions: %v", err)
	}
}

func TestSubscriptionAndInvoiceNeedLiveCustomer(t *testing.T) {
	s := New()
	a, b := newOrg(t, s, "A"), newOrg(t, s, "B")
	c, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	p, _ := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: "USD", UnitAmount: 100, Interval: Monthly}, t0)
	line := []Line{{Description: "Pro", Quantity: 1, UnitAmount: 100}}
	if err := s.SoftDeleteCustomer(a.ID, c.ID, t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: c.ID, PlanID: p.ID, Quantity: 1, Status: Active}, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("subscription for a deleted customer: %v", err)
	}
	if _, err := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: c.ID, Currency: "USD", Lines: line}, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("invoice for a deleted customer: %v", err)
	}
	live, _ := s.CreateCustomer(b.ID, "Other", "other@example.com", t0)
	if _, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: live.ID, PlanID: p.ID, Quantity: 1, Status: Active}, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("subscription for another org's customer: %v", err)
	}
}

func TestRestoreCustomer(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	jane, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	john, _ := s.CreateCustomer(a.ID, "John", "john@example.com", t0)
	if _, err := s.RestoreCustomer(a.ID, jane.ID, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("restore a customer that is not deleted: %v", err)
	}
	if err := s.SoftDeleteCustomer(a.ID, jane.ID, t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.RestoreCustomer(a.ID, jane.ID, t0.Add(30*24*time.Hour+time.Second)); !errors.Is(err, ErrNotFound) {
		t.Fatalf("restore after 30 days: %v", err)
	}
	if _, err := s.CreateCustomer(a.ID, "Jane 2", "jane@example.com", t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.RestoreCustomer(a.ID, jane.ID, t0.Add(time.Hour)); !errors.Is(err, ErrEmailTaken) {
		t.Fatalf("restore with the email taken: %v", err)
	}
	if err := s.DeleteCustomer(a.ID, john.ID); err != nil {
		t.Fatal(err)
	}
	if err := s.SoftDeleteCustomer(a.ID, jane.ID, t0); err != nil {
		t.Fatal(err)
	}
	if err := s.DeleteCustomer(a.ID, jane.ID); err != nil {
		t.Fatal(err)
	}
	if err := s.SoftDeleteCustomer(a.ID, jane.ID, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("delete an erased customer: %v", err)
	}
	other, _ := s.CreateCustomer(a.ID, "Other", "other@example.com", t0)
	if err := s.SoftDeleteCustomer(a.ID, other.ID, t0); err != nil {
		t.Fatal(err)
	}
	got, err := s.RestoreCustomer(a.ID, other.ID, t0.Add(30*24*time.Hour))
	if err != nil || got.DeletedAt != nil {
		t.Fatalf("restore at 30 days = %+v, %v", got, err)
	}
	if found, ok := s.FindCustomerByEmail(a.ID, "OTHER@example.com"); !ok || found.ID != other.ID {
		t.Fatalf("restored customer is not found by email: %+v, %v", found, ok)
	}
}

func TestPurgeDeletedCustomers(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	old, _ := s.CreateCustomer(a.ID, "Old", "old@example.com", t0)
	recent, _ := s.CreateCustomer(a.ID, "Recent", "recent@example.com", t0)
	kept, _ := s.CreateCustomer(a.ID, "Kept", "kept@example.com", t0)
	p, _ := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: "USD", UnitAmount: 100, Interval: Monthly}, t0)
	inv, err := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: old.ID, Currency: "USD", Lines: []Line{{Description: "Pro", Quantity: 1, UnitAmount: 100}}}, t0)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.SoftDeleteCustomer(a.ID, old.ID, t0); err != nil {
		t.Fatal(err)
	}
	if err := s.SoftDeleteCustomer(a.ID, recent.ID, t0.Add(20*24*time.Hour)); err != nil {
		t.Fatal(err)
	}
	_ = p
	now := t0.Add(31 * 24 * time.Hour)
	if n := s.PurgeDeletedCustomers(now); n != 1 {
		t.Fatalf("purged %d customers, want 1", n)
	}
	if _, ok := s.CustomerIncludingDeleted(a.ID, old.ID); ok {
		t.Fatal("purged customer is still there")
	}
	if _, ok := s.CustomerByID(recent.ID); !ok {
		t.Fatal("a customer deleted 11 days ago was purged")
	}
	if _, ok := s.Customer(a.ID, kept.ID); !ok {
		t.Fatal("a live customer was purged")
	}
	if got, ok := s.Invoice(a.ID, inv.ID); !ok || got.CustomerID != old.ID {
		t.Fatalf("invoice of a purged customer = %+v, %v", got, ok)
	}
	if n := s.PurgeDeletedCustomers(now); n != 0 {
		t.Fatalf("second purge removed %d", n)
	}
}

func TestDeletedCustomersSurviveSnapshot(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	jane, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	if err := s.SoftDeleteCustomer(a.ID, jane.ID, t0); err != nil {
		t.Fatal(err)
	}
	s2, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if _, ok := s2.CustomerIncludingDeleted(a.ID, jane.ID); !ok {
		t.Fatal("deleted customer lost in the snapshot")
	}
	if _, err := s2.CreateCustomer(a.ID, "Jane 2", "jane@example.com", t0); err != nil {
		t.Fatalf("email of a deleted customer is taken after a reload: %v", err)
	}
	if _, err := s2.RestoreCustomer(a.ID, jane.ID, t0); !errors.Is(err, ErrEmailTaken) {
		t.Fatalf("restore after a reload: %v", err)
	}
}
EOF
